n=24
out=[[0]*n for _ in range(n)]
# 5x5 panels of 4x4, separated by color-5 rows/columns
for i in range(n):
    if i%5==4:
        out[i]=[5]*n
    else:
        for j in range(n):
            if j%5==4: out[i][j]=5
# stamp demo silhouette in every panel; tint by the seed color for each panel row
shape={(0,2),(1,0),(1,1),(1,2),(1,3),(2,1),(2,2),(3,2)}
colors=[2,3,4,6,7]
for pr,color in enumerate(colors):
    for pc in range(5):
        for r,c in shape:
            out[pr*5+r][pc*5+c]=color
assert len(out)==24 and all(len(row)==24 for row in out)
print(out)

